DROP TABLE IF EXISTS `email_templates`;

CREATE TABLE `email_templates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `is_active` tinyint(1) DEFAULT '1',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Wild at Heart',
  `from_email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subject` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `last_updated_by` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email_templates_name_unique` (`name`),
  UNIQUE KEY `email_templates_slug_unique` (`slug`),
  KEY `email_templates_last_updated_by_foreign` (`last_updated_by`),
  CONSTRAINT `email_templates_last_updated_by_foreign` FOREIGN KEY (`last_updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

LOCK TABLES `email_templates` WRITE;
/*!40000 ALTER TABLE `email_templates` DISABLE KEYS */;

INSERT INTO `email_templates` (`id`, `is_active`, `name`, `slug`, `from_name`, `from_email`, `subject`, `body`, `notes`, `created_at`, `updated_at`, `last_updated_by`)
VALUES
	(3,1,'Attendee connected to host','attendee-connected-to-host',NULL,NULL,'We’ve sent your info to the host of [event_title]','[attendee_name],\r\n\r\nThank you for expressing interest in [event_title].\r\n\r\nWell done! Choosing to get your heart back as man is one of the riskiest things you can ever do.\r\n\r\nIt changes...everything.\r\n\r\nWe’ve sent the info you provided to [host_name] and you can expect to hear from them soon.\r\n\r\nIn the coming days, they will share more details about the event schedule and logistics.\r\n\r\nYou can learn more about Fires including a [video and podcast here](https://wildatheart.org/fires).\r\n\r\nWarm regards,\r\nWild at Heart','Triggered by the AttendeeObserver on creation\r\n\r\nAvailable placeholder variables\r\n\r\n- [attendee_name]\r\n- [event_title]\r\n- [host_name]','2024-04-03 10:47:00','2024-04-04 11:05:26',2),
	(4,1,'Attendee registered','attendee-registered',NULL,NULL,'[attendee_name] has expressed interest in your event.','[host_name],\r\n\r\nWe’ve got exciting news — [attendee_fullname] has expressed interest in your Fire!\r\n\r\nHere’s the scoop:\r\n\r\n- [attendee_fullname]\r\n- [attendee_email]\r\n- [attendee_phone]\r\n- [attendee_city], [attendee_state]\r\n\r\n\r\n[attendee_fullname] is expecting to hear from you soon, so be sure to reach out.\r\n\r\nIt\'s working. Your choice to risk hosting a Fire is already giving others hope.\r\n\r\nPlease don\'t hesitate to reach out if you have any questions or need assistance. We\'re honored to be alongside you in this mission.\r\n\r\nFor the Kingdom,\r\n\r\nWild at Heart','This is triggered from the AttendeeObserver which listens for when an Attendee is created. \r\n\r\nIt has the following placeholder variables available:\r\n\r\n- [host_name]\r\n- [attendee_fullname]\r\n- [attendee_email]\r\n- [attendee_phone]\r\n- [attendee_city]\r\n- [attendee_state]','2024-04-03 10:49:51','2024-04-04 10:51:42',2),
	(5,1,'Event approved','event-approved',NULL,NULL,'Your Event is live!','[event_host_name]\r\n\r\nIt’s official—your Fire is approved. Welcome to the revolution!\r\n\r\nHere are a few suggestions:\r\n\r\n**Share your fire.** Here’s your unique link to share with anyone who may be interested: [Fire Link]\r\n\r\n**Respond in a timely manner.** \r\n\r\nYou\'ll receive an email every time someone expresses interest in your event. It’s up to you to communicate all event details (date/time, location, etc). Please respond promptly as they’ll be waiting to hear from you.\r\n\r\n**Keep an eye on your mailbox.** \r\n\r\nWe’ll be sending you a Firestarter Kit to assist you in organizing the event.\r\n\r\nMen were never meant to bear the weight of their pain or their glory alone. So we lit a Fire. And now you are too!\r\n\r\nFires are a place men find themselves outrageously loved by God, and other men.\r\n\r\nWe are excited to have you on board and can\'t wait to see what God does with your Fire.\r\n\r\nIf you have any questions or require any assistance, please don\'t hesitate to reach out to us at [email_address]\r\n\r\nFor the Kingdom,\r\nJohn and Morgan','This is triggered from the ApproveEvent job which happens inside the VerifyEmailController and CreateEventController depending on the user profile.\r\n\r\nIt has the following placeholder variables available:\r\n\r\n- [event_host_name]\r\n- [Fire Link]\r\n- [email_address]','2024-04-03 10:52:08','2024-04-04 10:49:41',2),
	(6,1,'GIft requested','gift-requested',NULL,NULL,'📦 Your Gift Is Coming!','[event_host_name],\r\n\r\n**Keep an eye on your mailbox.** We’ll be sending you a Firestarter Kit to assist you in organizing the event.\r\n\r\nWe are excited to have you on board and can\'t wait to see what God does with your Fire.\r\n\r\nIf you have any questions or require any assistance, please don\'t hesitate to reach out to us at [email_address].\r\n\r\nFor the Kingdom,\r\n\r\nJohn and Morgan','This is triggered within the HandleSendGiftController and has the following placeholder variables available:\r\n\r\n- [event_host_name]\r\n- [email_address]','2024-04-03 10:53:15','2024-04-04 10:47:32',2),
	(9,1,'Send verification email','send-verification-email',NULL,NULL,'Please verify your new Fire','Great! One last step to complete your registration.\r\n\r\nClick on this link and let\'s light your Fire.\r\n\r\n[call_to_action_link] \r\n\r\nIf you did not create an account or do not recognize this email, please disregard it, and no further action is required.','This is triggered by the CreateEventController and ResendConfirmationEmail action.\r\n\r\nIt has the following placeholder variables:\r\n\r\n- [call_to_action_link]','2024-04-03 10:57:00','2024-04-04 10:45:01',2),
	(11,1,'Send welcome email','send-welcome-email',NULL,NULL,'Your Event is live!','[event_host_name],\r\n\r\nIt’s official—your Fire is live. Welcome to the revolution!\r\n\r\nHere are a few suggestions:\r\n\r\n**Share your Fire.** Here’s your unique link to share with anyone who may be interested: [Fire Link]([event_url])\r\n\r\n**Respond in a timely manner.** You\'ll receive an email every time someone expresses interest in your event. It’s up to you to communicate all event details (date/time, location, etc). Please respond promptly as they’ll be waiting to hear from you.\r\n\r\n**Keep an eye on your mailbox.** We’ll be sending you a Firestarter Kit to assist you in organizing the event.\r\n\r\nMen were never meant to bear the weight of their pain or their glory alone. So we lit a Fire. And now you are too!\r\n\r\nFires are a place men find themselves outrageously loved by God, and other men.\r\n\r\nWe are excited to have you on board and can\'t wait to see what God does with your Fire.\r\n\r\nIf you have any questions or require any assistance, please don\'t hesitate to reach out to us at [email_address]\r\n\r\nFor the Kingdom,\r\n\r\nJohn and Morgan','This is triggered from the CreateEventController and should has the following variable placeholders available\r\n\r\n- [event_host_name]\r\n- [event_url]\r\n- [email_address]','2024-04-03 10:59:08','2024-04-04 10:43:15',2),
	(13,1,'Becoming a King Retreat Event Created','becoming-a-king-retreat-event-created',NULL,NULL,'Important Details About Your Upcoming Becoming a King Retreat','Welcome.\r\n\r\nThank you for joining this rare and remarkable fellowship of like-hearted\r\nmen. You are among the few. You have arrived at a narrow gate leading to life\r\nas it was meant to be.\r\n\r\nHere\'s a link to your particular Becoming a King Retreat listing:\r\n[BAK Retreat Event Listing]([event_url])\r\n\r\nBefore your event, you\'ll want to review the Becoming a King Retreat facilitator’s guide. For the best experience, we recommend downloading and viewing all the videos from the [facilitator\'s guide](https://wildatheart.org/courses/becomingakingretreat).\r\n\r\nThe publisher is extending 50% off for all quantity purchases of Becoming a King resources for retreat leaders. This discount is for any BAK resource combination (books, videos, study guides) totaling 20 units or more. \r\n\r\nAccess that [discount here](https://churchsource.com/products/becoming-a-king-the-path-to-restoring-the-heart-of-a-man?variant=33084364259425#bulk-pricing), and use the coupon code BAK50 to purchase your materials.\r\n\r\nThe Becoming a King Retreat Leaders Slack Community is a growing fellowship of leaders able to offer prayer, encouragement, counsel, and camaraderie for other BAK leaders as we take this event to our communities around the world.\r\n\r\nFind other men like you around the globe and [join for free](https://join.slack.com/t/becomingaking-dp26537/shared_invite/zt-19kekg56a-kYvIm4Dh9nLFV_RaKN5DbA).\r\n\r\n\r\n## ADDITIONAL RESOURCES\r\n\r\nAs a group leader, you’re invited to have exclusive access to this private page: [Becoming a King Launch Team](https://www.BecomingAKing.com/LaunchTeam).\r\n\r\nI led a fellowship of leaders from around the globe through a six-week Zoom study of [Becoming a King](https://www.becomingaking.com/online-study/).\r\n\r\nLet this be fuel for you and a sincere welcome to the fellowship.\r\n\r\nAs a leader of a Becoming a King Retreat, I would like to invite you and your group to join me and other leaders for an exclusive live online gathering where you can ask deeper questions, pray together, and share your stories.\r\n\r\n[Fill out the form](https://docs.google.com/forms/d/e/1FAIpQLScmCNW_ID08wUbanNEBKBlWvjMnQRqbXEHUdaAAzkAbGJGjcA/viewform) to add yourself and your group to the list. We offer these gatherings to new groups every several months, so we will be in touch when spots are available for you and the men from your event to join us.\r\n\r\nIf you have questions, please don\'t hesitate to [reach out to us](https://help.wildatheart.org/hc/en-us/requests/new).\r\n\r\nFor the Kingdom,\r\nMorgan',NULL,'2024-04-09 21:39:54','2024-05-28 17:16:29',1118),
	(15,1,'Becoming a King Experience Created','becoming-a-king-experience-created',NULL,NULL,'Important Details About Your Upcoming Becoming a King Group','Welcome! You are among the few. Well done.\r\n\r\nHere\'s a link to your particular listing:\r\n[BAK Experience Listing]([event_url])\r\n\r\nBefore your event you\'ll want to review the [Becoming a King Group Facilitator\'s Guide](https://wildatheart.org/courses/becomingaking).\r\n\r\nFor the best experience we recommend downloading the videos from the Becoming a King Group Facilitator\'s Guide.\r\n\r\nYou\'ll find a video collection of leading allies around the globe through a weekly [Becoming a King study](https://www.becomingaking.com/online-study/).\r\n\r\nP.S. As a group leader we\'d like to give you exclusive access to this private page. [Find out more](https://www.BecomingAKing.com/LaunchTeam).\r\n\r\nAs a leader of a Becoming a King group, I would like to invite you, and your group, to join me and other leaders for an exclusive live online gathering where you can ask deeper questions, pray together and share your stories. \r\n\r\n[Fill out the form](https://docs.google.com/forms/d/e/1FAIpQLScmCNW_ID08wUbanNEBKBlWvjMnQRqbXEHUdaAAzkAbGJGjcA/viewform) to add yourself and your group to the list. \r\n\r\nWe are offering them every several months to new groups so we will be in touch when spots are available for you and your group to join us.\r\n\r\nThe publisher has offered an exclusive promotion for Becoming a King leaders to purchase study guides and books at 50% off for qualifying quantities.\r\n\r\nYou can [purchase them here](https://shrsl.com/35x5h) or [talk directly with\r\na representative to get the full discount](https://churchsource.com/pages/talk-to-a-resource-specialist).\r\n\r\nIf you have questions please don\'t hesitate to [reach out to us](https://help.wildatheart.org/hc/en-us/requests/new).\r\n\r\nFor the Kingdom,\r\nMorgan',NULL,'2024-04-09 21:47:08','2024-05-28 17:13:18',1118),
	(19,1,'WAH Retreat Created','wah-retreat-created',NULL,NULL,'Important Details About Your Upcoming Wild at Heart Retreat','Hey [event_host_name],\r\n\r\nWe\'re excited to see your interest in leading a Wild at Heart Retreat. You can\r\naccess the [Facilitator\'s Guide at any time](https://wildatheart.org/courses/basic).\r\n\r\nWe encourage you to join the [Wild at Heart Retreat Facilitators community](https://join.slack.com/t/wildatheartbasic/shared_invite/zt-b25maoxe-0BXGonXF4L2jek1NwQdV7Q).\r\n\r\nRegistration is free and only open to BASIC facilitators. If you have\r\nquestions, that is the best way to reach us.\r\n\r\nAll the best,\r\nThe Wild at Heart Team\r\n\r\nHere\'s a link to your listing:\r\n[Wild at Heart Retreat Listing]([event_url])\r\n\r\nYou can view and edit your listing on your [My Account page](https://local.wildatheart.org/profile)\r\n\r\nBefore your event you\'ll want to review the [Wild at Heart Retreat manual](https://wildatheart.org/courses/basic).\r\n\r\nFor the best experience we recommend downloading the videos from the course\r\nguide.',NULL,'2024-04-10 15:06:49','2024-05-28 16:58:48',1118),
	(20,1,'Wild at Heart Experience Created','wild-at-heart-experience-created',NULL,NULL,'Important Details About Your Upcoming Wild at Heart Small Group','Hey [event_host_name],\r\n\r\nWe\'re so excited you\'ve decided to host a Wild at Heart Small Group. If you have any questions, please reply and let us know.\r\n\r\nWe\'re including some helpful links below.\r\n\r\nWe\'re praying for you and we\'re excited to partner with you on this journey.\r\n\r\nAgain if you have any questions, just reply and let us know.\r\n\r\n\r\nHere\'s a link to your listing:\r\n[WAH Retreat Listing]([event_url])\r\n\r\n\r\nBefore your event you\'ll want to review the [Wild at Heart Small Group manual](https://wildatheart.org/courses/wildatheart).\r\n\r\nFor the best experience we recommend downloading the videos from the course\r\nguide.\r\n\r\nDo you have any questions? Join the Wild at Heart team and your fellow\r\nfacilitators in our [online community](https://join.slack.com/t/wildatheartbasic/shared_invite/zt-b25maoxe-0BXGonXF4L2jek1NwQdV7Q). \r\n\r\nRegistration is free and only open to Retreat facilitators. Ask for prayer for your event and learn best practices from small group facilitators around the world.',NULL,'2024-04-10 15:39:37','2024-05-28 16:56:58',1118),
	(23,1,'Captivating Experience Created','captivating-experience-created',NULL,NULL,'Important Details About Your Upcoming Captivating Small Group','Hey [event_host_name],\r\n\r\n We\'re so excited you\'ve decided to\r\nhost a Captivating Small Group. If you have any questions, please reply and\r\nlet us know.\r\n\r\nWe\'re including some helpful links below.\r\n\r\nWe\'re praying for you and we\'re excited to partner with you on this journey.\r\n\r\nAgain if you have any questions, just reply and let us know.\r\n\r\nHere\'s a link to your listing:\r\n[Captivating Retreat Listing]([event_url])\r\n\r\n\r\nBefore your event you\'ll want to review the [Captivating Small Group manual](https://wildatheart.org/courses/captivating).\r\n\r\nFor the best experience we recommend downloading the videos from the course\r\nguide.\r\n\r\nDo you have any questions? Join the Wild At Heart team and your fellow\r\nfacilitators in our [online community](https://join.slack.com/t/wildatheartbasic/shared_invite/zt-b25maoxe-0BXGonXF4L2jek1NwQdV7Q). \r\n\r\nRegistration is free and only open to small group facilitators. Ask for\r\nprayer for your event and learn best practices from small group facilitators\r\naround the world.',NULL,'2024-04-10 15:41:24','2024-05-28 16:55:50',1118),
	(24,1,'Monthly fire cleanup email to host','monthly-fire-cleanup-email-to-host',NULL,NULL,'Is your Fire - [event_name] - still burning?','Hi [event_host_name],\r\n\r\nWe appreciate your commitment to hosting a Fire through Wild at Heart, providing a space for men to connect and experience God through shared stories. We’ll reach out regularly to ensure all Fires on the map are intended to be active so that men contacting hosts are served well. \r\n\r\nPlease click one of the buttons below to indicate what you’d like the status of your Fire to be. If you keep the Fire active, we won’t ask again for another 90 days. \r\n\r\n[button_active]\r\n\r\n[button_inactive]\r\n\r\n[Have questions or need help?](https://local.wildatheart.org/support)\r\n\r\nIf you haven’t hosted a Fire yet, how can we help? \r\n\r\nThanks for partnering with us! \r\n\r\n-Wild at Heart Team','This is used in the daily task to check if a Fire has been updated in the last 90 days.\r\n\r\nPlaceholder variables available are:\r\n- [host_name]\r\n- [button_active]\r\n- [button_inactive]','2024-04-23 10:29:07','2024-05-02 14:31:47',2),
	(25,1,'Fire made inactive','fire-made-inactive',NULL,NULL,'Your Fire - [event_name] - has been deactivated','We have deactivated your Fire and it no longer shows on the Wild at Heart map. Feel free to restart your Fire anytime by logging into https://local.wildatheart.org/ and clicking on the avatar. \r\n\r\nAs always, let us know if there is any way we can help. \r\n\r\nWild at Heart team.','This email is sent when the monthly email to hosts is sent to check on the status of their Fire.\r\n\r\nIf they make their Fire inactive, then we\'ll send this email.','2024-04-24 14:33:23','2024-05-02 14:16:09',2),
	(26,1,'Fire deactivating soon','fire-deactivating-soon',NULL,NULL,'Your Fire - [event_name] - Will Deactivate Soon','Hi [host_name],\r\nJust a reminder, if you would like your Fire to remain active and listed on the map at local.wildatheart.org, please click the button below. \r\n\r\n[button_active]\r\n\r\nIf you\'d like to deactivate your fire click this button:\r\n\r\n[button_inactive]\r\n\r\nIf one of the above buttons is not selected, we will deactivate your Fire in 3 days to ensure all Fires listed on the map are still active. \r\n\r\n[Have questions or need help?](https://local.wildatheart.org/support]\r\n\r\nIf you haven’t hosted a Fire yet, how can we help? \r\n\r\nThanks for partnering with us! \r\n\r\n-Wild at Heart Team','This is used in the daily task to check if a Fire has been updated in the last 90 days. The \'Is your Fire still burning?\' email is sent first and then 3 days later this email is sent. \r\n\r\nPlaceholder variables available are:\r\n- [host_name]\r\n- [button_active]\r\n- [button_inactive]','2024-05-01 13:52:55','2024-05-02 16:17:10',1050),
	(27,1,'Survival School Created','survival-school-created',NULL,NULL,'Important Details About Your Upcoming Survival School','body for survival school',NULL,'2024-05-28 17:17:36','2024-05-28 17:17:51',1118),
	(28,1,'Captivating Retreat Created','captivating-retreat-created',NULL,NULL,'Important Details About Your Upcoming Captivating Retreat','Captivating Retreat content',NULL,'2024-05-28 17:18:50','2024-05-28 17:18:50',NULL),
	(29,1,'','','Wild at Heart',NULL,'','',NULL,NULL,NULL,NULL);

